// One list across all three feeds, most recent first, capped to the
// classifier contract's own candidatesPerRun — one source of truth for
// that number rather than a second hardcoded copy here.
const RECENT_DAYS = 2;
const MAX_CANDIDATES = $('Rumor classifier contract').first().json.candidatesPerRun ?? 15;
const cutoff = Date.now() - RECENT_DAYS * 24 * 60 * 60 * 1000;

const items = $input.all()
  .map((item) => item.json)
  .filter((a) => a.link && a.title)
  .map((a) => ({
    title: String(a.title).trim(),
    link: String(a.link).trim(),
    pubDate: a.isoDate || a.pubDate || '',
    snippet: String(a.contentSnippet || a.content || '').replace(/<[^>]+>/g, ' ').slice(0, 800),
  }))
  .filter((a) => {
    const t = Date.parse(a.pubDate);
    return !Number.isNaN(t) && t >= cutoff;
  })
  .sort((a, b) => Date.parse(b.pubDate) - Date.parse(a.pubDate))
  .slice(0, MAX_CANDIDATES);

return items.map((a) => ({ json: a }));

