// Pull the forced tool call out of each response and flatten every
// article's rumors[] into one flat list. Most articles naming zero
// qualifying models is the expected, normal result, not a failure.
const candidates = $('Cap + build candidates').all();
const rumors = [];

const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const src = candidates[i]?.json;
  if (!src) continue;

  const block = (items[i].json.content ?? []).find((b) => b.type === 'tool_use');
  const result = block?.input;
  if (!result || !Array.isArray(result.rumors)) continue;

  for (const r of result.rumors) {
    const slug = String(r.slug ?? '').trim();
    const name = String(r.name ?? '').trim();
    const provider = String(r.provider ?? '').trim();
    const summary = String(r.summary ?? '').trim();
    if (!slug || !name || !provider || summary.length < 10) continue;

    // Validated rather than trusted — one malformed date would otherwise
    // fail Zod validation for the entire batch on the receiving end, not
    // just this one rumor.
    const rawDate = String(r.predictedDate ?? '').trim();
    const predictedDate = /^\d{4}-\d{2}-\d{2}$/.test(rawDate) ? rawDate : null;

    rumors.push({
      slug,
      name,
      provider,
      summary: summary.slice(0, 500),
      sourceUrl: src.link,
      ...(predictedDate ? { predictedDate } : {}),
    });
  }
}

if (!rumors.length) return [];
return [{ json: { rumors } }];
